// BobaLog 品牌資料(完整版草稿)
// 包含原本就有的 3 個品牌 + 新確認(OK)的品牌,新品牌會持續加在陣列最後面
// 全部弄完後,直接整份複製貼到 lib/brands.ts 取代即可

export type Drink = {
  name: string;
  category?: string;
  note?: string; // 附加標籤,例如:季節限定、無咖啡因、限冷飲、固定冰量
  prices: {
    M: number;
    L: number;
  };
  id?: string;
};

export type AddOn = {
  name: string;
  price: number;
};

export type Brand = {
  name: string;
  slug: string;
  icon: string;
  drinks: Drink[];
  addOns?: AddOn[]; // 這個品牌可加的料(例如珍珠、椰果),沒有就不用寫這個欄位
};

export type BrandSummary = {
  name: string;
  slug: string;
  icon: string;
  addOns?: AddOn[];
  drinkCount: number;
};

